package com.example.finance.online;
import com.example.finance.common.*;
import com.example.finance.ledger.FinanceLedger;
import com.example.finance.payment.*;
import com.example.finance.tuition.*;
import jakarta.persistence.*;
import java.math.BigDecimal;
import java.time.*;
import java.util.*;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.*;
@Service @RequiredArgsConstructor @Transactional(isolation=Isolation.READ_COMMITTED)
public class OnlineSettlement {
 private final OnlineOrderRepository orders; private final ProviderEventRepository events; private final ProviderTransactionRepository transactions; private final TuitionRepository tuition; private final PaymentRepository payments; private final FinanceLedger ledger; private final EntityManager em;
 private LocalDateTime now(){return LocalDateTime.now(BusinessTime.ZONE);}
 private void emit(OnlineOrder o,String type){String key=type+":"+o.getId()+(type.equals("PAYMENT_REVIEW_REQUIRED")?":"+o.getVersion():"");if(em.createQuery("select count(e) from PaymentOutbox e where e.eventKey=:key",Long.class).setParameter("key",key).getSingleResult()>0)return;var e=new PaymentOutbox();e.setEventKey(key);e.setType(type);e.setOrderId(o.getId());e.setStudentId(o.getStudentId());e.setReceiptId(o.getReceiptId());e.setCreatedAt(now());em.persist(e);com.example.finance.notification.StudentEvents.add(em,"finance:online:"+key,"PAYMENT",type,type.equals("PAYMENT_SUCCEEDED")?"Thanh toán đã ghi nhận":"Cập nhật đơn thanh toán","Mở đơn để kiểm tra trạng thái từ trung tâm.",o.getStudentId(),null,null,null,o.getBranchId(),o.getReceiptId()==null?"PAYMENT_ORDER":"RECEIPT",o.getReceiptId()==null?o.getId():o.getReceiptId().toString(),null,null);}
 private void review(OnlineOrder o,String reason){if(!"SUCCEEDED".equals(o.getState()))o.setState("REVIEW_REQUIRED");o.setReviewCode(reason);o.setUpdatedAt(now());emit(o,"PAYMENT_REVIEW_REQUIRED");}
 public String process(Long eventId,boolean reconciled){var initial=events.findById(eventId).orElseThrow(ApiException::missing);var first=orders.findByMerchantRef(initial.getMerchantRef()).orElse(null);em.detach(initial);if(first!=null)em.detach(first);Tuition t=null;OnlineOrder o=null;if(first!=null){t=tuition.lock(first.getTuitionId()).orElseThrow(ApiException::missing);em.refresh(t);o=orders.lock(first.getId()).orElseThrow(ApiException::missing);em.refresh(o);}var e=em.find(ProviderEvent.class,eventId,LockModeType.PESSIMISTIC_WRITE);em.refresh(e);if(!reconciled&&(e.getStatus().equals("PROCESSED")||e.getStatus().equals("IGNORED")))return "00";if(e.getStatus().equals("REVIEW_REQUIRED")&&!reconciled)return e.getResultCode()!=null&&e.getResultCode().equals("AMOUNT_MISMATCH")?"04":o==null?"01":"00";if(o!=null){e.setOrderId(o.getId());e.setBranchId(o.getBranchId());}e.setProcessedAt(now());
  if(!e.getOutcome().equals("PAID")){if(o!=null&&(e.getAmount().compareTo(o.getAmount())!=0||!e.getMerchantCode().equals(o.getMerchantCode()))){review(o,"AMOUNT_MISMATCH");e.setStatus("REVIEW_REQUIRED");e.setResultCode("AMOUNT_MISMATCH");return "04";}if(o==null){e.setStatus("REVIEW_REQUIRED");e.setResultCode("UNKNOWN_ORDER");return "01";}if(o.getState().equals("SUCCEEDED")){if(e.getOutcome().equals("REVIEW"))review(o,"PROVIDER_STATUS_REVIEW");e.setStatus("IGNORED");return "00";}if(e.getOutcome().equals("REVIEW")){review(o,"PROVIDER_STATUS_REVIEW");e.setStatus("REVIEW_REQUIRED");e.setResultCode("PROVIDER_STATUS_REVIEW");}else{if(!o.getState().equals("REVIEW_REQUIRED")&&e.getOutcome().equals("FAILED")){o.setState(now().isAfter(o.getExpiresAt())?"EXPIRED":"FAILED");o.setUpdatedAt(now());}e.setStatus("PROCESSED");}return "00";}
  var tx=transactions.findByMerchantCodeAndTransactionNo(e.getMerchantCode(),e.getTransactionNo()).orElse(null);if(tx==null){tx=new ProviderTransaction();tx.setMerchantCode(e.getMerchantCode());tx.setTransactionNo(e.getTransactionNo());tx.setOrderId(o==null?null:o.getId());tx.setAmount(e.getAmount());tx.setPaidAt(e.getPaidAt());tx.setCreatedAt(now());transactions.saveAndFlush(tx);}else if(!Objects.equals(tx.getOrderId(),o==null?null:o.getId())||tx.getAmount().compareTo(e.getAmount())!=0){if(o!=null)review(o,"TRANSACTION_CONFLICT");e.setStatus("REVIEW_REQUIRED");e.setResultCode("TRANSACTION_CONFLICT");return "00";}
  String problem=o==null?"UNKNOWN_ORDER":!o.getMerchantCode().equals(e.getMerchantCode())?"MERCHANT_MISMATCH":e.getAmount().compareTo(o.getAmount())!=0?"AMOUNT_MISMATCH":null;
  if(problem==null&&o.getState().equals("SUCCEEDED")){if(Objects.equals(tx.getReceiptId(),o.getReceiptId())){if(reconciled){long unresolved=em.createQuery("select count(p) from ProviderTransaction p where p.orderId=:order and p.state='REVIEW_REQUIRED'",Long.class).setParameter("order",o.getId()).getSingleResult();if(unresolved==0)o.setReviewCode(null);o.setUpdatedAt(now());}e.setStatus("PROCESSED");return "00";}problem="EXTRA_TRANSACTION";}
  if(problem==null&&(!Objects.equals(t.getStudentId(),o.getStudentId())||!Objects.equals(t.getEnrollmentId(),o.getBillingRootId())||!Objects.equals(t.getBranchId(),o.getBranchId())||!"VND".equals(t.getCurrency())||t.getStatus()==Tuition.Status.CANCELLED))problem="TUITION_CHANGED";
  if(problem==null&&!reconciled&&(now().isAfter(o.getExpiresAt())||e.getPaidAt().isAfter(o.getExpiresAt())||Set.of("EXPIRED","FAILED","REVIEW_REQUIRED").contains(o.getState())))problem="LATE_OR_CHANGED_STATE";
  if(problem==null){try{ledger.requireSynced(t);}catch(ApiException ex){problem="LEDGER_UNVERIFIED";}}
  if(problem==null&&e.getAmount().compareTo(t.getAmount().subtract(ledger.net(t.getId())))>0)problem="OUTSTANDING_CHANGED";
  if(problem==null&&!reconciled){long other=em.createQuery("select count(p) from ProviderTransaction p,OnlineOrder other where p.orderId=other.id and other.tuitionId=:tuition and p.state='REVIEW_REQUIRED' and p.id<>:id",Long.class).setParameter("tuition",t.getId()).setParameter("id",tx.getId()).getSingleResult();if(other>0)problem="OTHER_TRANSACTION_REVIEW";}
  if(problem!=null){tx.setReviewCode(problem);if(o!=null)review(o,problem);e.setStatus("REVIEW_REQUIRED");e.setResultCode(problem);return problem.equals("UNKNOWN_ORDER")?"01":problem.equals("AMOUNT_MISMATCH")?"04":"00";}
  var payment=new Payment();payment.setTuitionId(t.getId());payment.setBranchId(t.getBranchId());payment.setAmount(e.getAmount());payment.setPaymentMethod(Payment.PaymentMethod.BANK_TRANSFER);payment.setReferenceCode(e.getTransactionNo());payment.setRequestKey("ONLINE-"+o.getId());payment.setReceiptNo("PT-"+UUID.randomUUID());payment.setPaidAt(e.getPaidAt());payment.setRecordedByName("VNPAY sandbox");payment.setNote("Online order "+o.getId());payments.saveAndFlush(payment);ledger.setNet(t,ledger.net(t.getId()));tx.setReceiptId(payment.getId());tx.setState("ALLOCATED");tx.setReviewCode(null);o.setReceiptId(payment.getId());o.setState("SUCCEEDED");o.setReviewCode(null);o.setUpdatedAt(now());e.setStatus("PROCESSED");e.setResultCode("ALLOCATED");emit(o,"PAYMENT_SUCCEEDED");return "00";
 }
 public void expire(String id){var first=orders.findById(id).orElse(null);if(first==null)return;em.detach(first);tuition.lock(first.getTuitionId()).orElseThrow(ApiException::missing);var o=orders.lock(id).orElseThrow(ApiException::missing);em.refresh(o);if(Set.of("CREATED","PENDING").contains(o.getState())&&now().isAfter(o.getExpiresAt())){o.setState("EXPIRED");o.setUpdatedAt(now());emit(o,"PAYMENT_EXPIRED");}}
}
